package com.morongaming.forsakenrealm;
import java.math.BigInteger;import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;import java.util.*;
/** Merchant-owned catalogue and server-computed marginal quantity quotes. */
final class TraderView extends View {
 interface Host{JSONObject merchant();long coins(String currency);String status();void trade(String item,boolean buy,int amount,long total,String currency);void repair(String item);void close();}
 final Host host;final MenuArt art;final MenuFrame f=new MenuFrame();boolean buying=true,pressed;int page,category,quantity=1;String selected="";float downX,downY;
 String[] categories(){JSONObject m=host.merchant();JSONArray offers=m==null?null:m.optJSONArray("offers");ArrayList<String> names=new ArrayList<>();if(offers!=null)for(int i=0;i<offers.length();i++){JSONObject o=offers.optJSONObject(i);if(o!=null)names.add(o.optString("category"));}return MerchantCategories.names(m==null?"":m.optString("shop"),names.toArray(new String[0]));}
 TraderView(Context c,Host h){super(c);host=h;art=MenuArt.get(c);setContentDescription("Trader catalogue, details and quantity");}
 ArrayList<JSONObject> rows(){ArrayList<JSONObject> out=new ArrayList<>();JSONObject m=host.merchant();String[] categories=categories();if(categories.length==0)return out;category=Math.max(0,Math.min(category,categories.length-1));JSONArray a=m==null?null:m.optJSONArray("offers");if(a!=null)for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&categories[category].equals(MerchantCategories.category(m.optString("shop"),o.optString("category"))))out.add(o);}return out;}
 JSONObject selection(ArrayList<JSONObject> a){for(JSONObject o:a)if(selected.equals(o.optString("item")))return o;if(a.isEmpty())return null;selected=a.get(0).optString("item");quantity=1;return a.get(0);}
 boolean affordable(long price,String currency){return CoinMath.canAfford(host.coins("copper"),host.coins("silver"),host.coins("gold"),price,currency);}

 int maximum(JSONObject o){return Math.min(100,o.optInt(buying?"stock":"owned"));}
 long quote(JSONObject o){JSONArray q=o.optJSONArray(buying?"buyQuotes":"sellQuotes");return q!=null&&quantity<q.length()?q.optLong(quantity,-1):quantity==1?o.optLong(buying?"buy":"sell"):-1;}
 protected void onDraw(Canvas c){f.begin(c,this);JSONObject m=host.merchant();f.text(c,m==null?"TRADER OUT OF REACH":m.optString("name").toUpperCase(),24,36,25,600);f.text(c,"EXIT SHOP",820,36,18,120);f.text(c,"Copper: "+host.coins("copper")+"   Silver: "+host.coins("silver")+"   Gold: "+host.coins("gold"),24,75,17,530);JSONObject standing=m==null?null:m.optJSONObject("standing");f.text(c,standing==null?"":("Standing: "+standing.optLong("reputation")+" | "+standing.optString("faction")+" | "+standing.optString("access")),570,75,15,370);
 String[] categories=categories();category=Math.max(0,Math.min(category,categories.length-1));for(int i=0;i<categories.length;i++){f.panel(c,20,100+i*43,164,35,category==i);f.text(c,categories[i],31,124+i*43,16,142);}f.panel(c,20,413,78,42,buying);f.text(c,"BUY",42,441,16,55);f.panel(c,106,413,78,42,!buying);f.text(c,"SELL",122,441,16,57);
 ArrayList<JSONObject> list=rows();page=Math.min(page,Math.max(0,(list.size()-1)/6));JSONObject chosen=selection(list);
 for(int i=0;i<6&&page*6+i<list.size();i++){JSONObject o=list.get(page*6+i);float x=200+i%3*145,y=100+i/3*169;f.panel(c,x,y,135,158,o==chosen);art.item(c,o.optString("item"),x+27,y+8,80);f.text(c,o.optString("name"),x+7,y+110,15,121);f.text(c,o.optLong(buying?"buy":"sell")+" "+o.optString("currency","gold")+" / next",x+7,y+132,14,121);f.text(c,(buying?"Stock: ":"Owned: ")+o.optInt(buying?"stock":"owned"),x+7,y+151,12,121);}
 f.panel(c,648,100,292,338,false);if(chosen!=null){quantity=Math.max(1,Math.min(quantity,Math.max(1,maximum(chosen))));art.item(c,chosen.optString("item"),740,109,90);f.text(c,chosen.optString("name"),663,222,20,262);JSONObject def=art.items.get(chosen.optString("item"));if(def!=null){String detail=def.has("damage")?"Damage: "+def.optInt("damage")+" • Range: "+def.optInt("range"):def.has("armorSlot")?"Armor slot: "+def.optString("armorSlot"):"Weight: "+def.optDouble("weight")+" per item";f.text(c,detail,663,247,15,262);}f.text(c,chosen.optString("rarityName","Common")+(chosen.optInt("equipmentTier")>0?" • Level "+chosen.optInt("equipmentTier"):"")+" • Stock "+chosen.optInt("stock"),663,273,15,262);
 f.panel(c,663,286,48,35,false);f.text(c,"−",678,312,22,25);f.text(c,"Quantity: "+quantity,727,310,17,140);f.panel(c,877,286,48,35,false);f.text(c,"+",892,312,22,25);long price=quote(chosen);boolean ok=maximum(chosen)>0&&price>=0&&(!buying||affordable(price,chosen.optString("currency","gold")));f.panel(c,663,333,262,40,ok);f.text(c,(buying?"BUY":"SELL")+" • "+(price<0?"Quote unavailable":price+" "+chosen.optString("currency","gold")),685,360,18,218);if(!buying){f.panel(c,663,383,262,40,chosen.optInt("owned")>0);f.text(c,"SELL ALL • "+chosen.optLong("sellAll")+" "+chosen.optString("currency","gold"),682,410,17,226);}else if(def!=null&&def.has("armorSlot")&&chosen.optInt("owned")>0){f.panel(c,663,383,262,40,false);f.text(c,"REPAIR CARRIED ARMOR",680,410,16,230);}}
 f.text(c,"< PREV",200,470,16,100);f.text(c,"Page "+(page+1)+" / "+Math.max(1,(list.size()+5)/6),350,470,15,180);f.text(c,"NEXT >",550,470,16,90);f.text(c,host.status(),24,515,14,910);c.restore();}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY());int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){pressed=true;downX=x;downY=y;return true;}if(action==MotionEvent.ACTION_CANCEL||action==MotionEvent.ACTION_POINTER_DOWN){pressed=false;return true;}if(action!=MotionEvent.ACTION_UP)return true;if(!pressed)return true;pressed=false;if(Math.hypot(x-downX,y-downY)>14)return true;if(x>810&&y<52){host.close();return true;}if(x>=20&&x<=184&&y>=100&&y<100+categories().length*43&&(y-100)%43<35){category=(int)((y-100)/43);page=0;selected="";quantity=1;}if(x>=20&&x<=184&&y>=413&&y<=455){buying=x<100;quantity=1;}
 ArrayList<JSONObject> a=rows();if(x>=200&&x<635&&y>=100&&y<438&&(x-200)%145<135&&(y-100)%169<158){int i=page*6+(int)((y-100)/169)*3+(int)((x-200)/145);if(i<a.size()){selected=a.get(i).optString("item");quantity=1;}}
 if(y>=447&&y<=485){if(x>=200&&x<300)page=Math.max(0,page-1);if(x>=540&&x<635)page=Math.min(Math.max(0,(a.size()-1)/6),page+1);}JSONObject o=selection(a);if(o!=null){if(y>=286&&y<=321){if(x>=663&&x<=711)quantity=Math.max(1,quantity-1);if(x>=877&&x<=925)quantity=Math.min(Math.max(1,maximum(o)),quantity+1);}if(x>=663&&x<=925&&y>=333&&y<=373&&maximum(o)>0&&quote(o)>=0&&(!buying||affordable(quote(o),o.optString("currency","gold"))))host.trade(o.optString("item"),buying,quantity,quote(o),o.optString("currency","gold"));if(x>=663&&x<=925&&y>=383&&y<=423){if(!buying&&o.optInt("owned")>0)host.trade(o.optString("item"),false,o.optInt("owned"),o.optLong("sellAll"),o.optString("currency","gold"));else if(buying&&o.optInt("owned")>0){JSONObject def=art.items.get(o.optString("item"));if(def!=null&&def.has("armorSlot"))host.repair(o.optString("item"));}}}invalidate();return true;}
}

